mod solution;

fn main() {
    let cases = [
    (r#"[(1,3),(-2,2),(2,-2),(5,1)]"#, r#"-2:2,2:-2"#),
    (r#"[(0,1),(2,0),(0,3)]"#, r#"0:1,2:0"#),
    (r#"
[(0,1),(2,0),(0,3)]
"#, r#"0:1,2:0"#),
    (r#"  
[(1,3),(-2,2),(2,-2),(5,1)]
  "#, r#"-2:2,2:-2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS closest-k-heap");
}
